harness_verification_workspace_control() {
    local action=${1:?action required} change=${2:?change required}
    [[ "$action" == cleanup || "$action" == assert-clean ]] || return 2
    harness_with_verification_workspace_capability "$change" "$action" \
        scripts/verification_workspace.sh "$action" "$change"
}
harness_run_evidence_command() {
    local change=${1:?change required}
    shift
    [[ $# -gt 0 ]] || return 2
    case "$1" in
        scripts/verification_workspace.sh|./scripts/verification_workspace.sh)
            harness_with_verification_workspace_capability "$change" run "$@"
            ;;
        *) "$@" ;;
    esac
}
harness_persist_project_command_evidence() {
    local change=${1:?change required} command_id=${2:?command ID required}
    local exit_code=${3:?exit code required} output_sha256=${4:?output digest required}
